+FutureResult<> EncFsBackend::changePassword(const Device &device, const Vault::Payload &payload)
+{
+    auto process = encfsctl({
+        "autopasswd", // read the current and the new password from stdin
+        device.data(),
+    });
+
+    auto result = makeFuture(process, [](QProcess *process) {
+        if (process->exitStatus() == QProcess::NormalExit && process->exitCode() == 0) {
+            return Result<>::success();
+        }
+
+        const auto out = process->readAllStandardOutput();
+        const auto err = process->readAllStandardError();
+
+        if (out.contains("Invalid password")) {
+            return Result<>::error(Error::BackendError, i18n("The current password is incorrect."));
+        }
+
+        return Result<>::error(Error::CommandError, i18n("Unable to perform the operation"), out, err);
+    });
+
+    process->write(payload[KEY_PASSWORD].toString().toUtf8() + "\n");
+    process->write(payload[KEY_NEW_PASSWORD].toString().toUtf8() + "\n");
+
+    return result;
+}
