+FutureResult<> GocryptfsBackend::changePassword(const Device &device, const Vault::Payload &payload)
+{
+    auto passwdProcess = process("gocryptfs", {"-passwd", device.data()}, {});
+
+    auto result = makeFuture(passwdProcess, [](QProcess *process) {
+        auto const exitCode = static_cast<ExitCode>(process->exitCode());
+
+        switch (exitCode) {
+        case ExitCode::Success:
+            return Result<>::success();
+
+        case ExitCode::WrongPassword:
+            return Result<>::error(Error::BackendError, i18n("The current password is incorrect."));
+
+        case ExitCode::CannotWriteConfig:
+            return Result<>::error(Error::BackendError, i18n("Cannot write gocryptfs.conf inside cipher directory, check your permissions."));
+
+        default:
+            return Result<>::error(Error::CommandError,
+                                   i18n("Unable to perform the operation (error code %1).", QString::number((int)exitCode)),
+                                   process->readAllStandardOutput(),
+                                   process->readAllStandardError());
+        }
+    });
+
+    // Write the current password, then the new one twice (insert and confirm)
+    passwdProcess->write(payload[KEY_PASSWORD].toString().toUtf8() + "\n");
+    for (int i = 0; i < 2; ++i) {
+        passwdProcess->write(payload[KEY_NEW_PASSWORD].toString().toUtf8() + "\n");
+    }
+
+    return result;
+}
