+FutureResult<> Vault::changePassword(const Payload &payload)
+{
+    // We can not change the password of something that has not been
+    // registered with us before
+    if (!d->data) {
+        return errorResult(Error::BackendError, i18n("The vault is unknown; cannot change its password."));
+    }

+    if (isOpened()) {
+        return errorResult(Error::BackendError, i18n("The vault needs to be locked to change its password."));
+    }
+
+    return d->data->backend->changePassword(d->device, payload);
+}

