+PasswordChangeWidget::PasswordChangeWidget()
+    : DialogDsl::DialogModule(true)
+    , d(new Private())
+{
+    d->ui.setupUi(this);
+
+    auto messageWidget = new KMessageWidget(d->ui.labelNotice->text(), this);
+    messageWidget->setMessageType(KMessageWidget::Information);
+    messageWidget->setCloseButtonVisible(false);
+    messageWidget->setWordWrap(true);
+    static_cast<QBoxLayout *>(layout())->insertWidget(0, messageWidget);
+
+    d->ui.labelNotice->hide();
+
+    const auto updateIsValid = [this] {
+        const bool hasCurrentPassword = !d->ui.editCurrentPassword->password().isEmpty();
+        const bool hasNewPassword = !d->ui.editNewPassword->password().isEmpty();
+        const auto status = d->ui.editNewPassword->passwordStatus();
+
+        if (hasNewPassword) {
+            setIsValid(hasCurrentPassword && (status == KNewPasswordWidget::StrongPassword || status == KNewPasswordWidget::WeakPassword));
+        } else {
+            // Leaving everything empty keeps the current password
+            setIsValid(!hasCurrentPassword && status != KNewPasswordWidget::PasswordNotVerified);
+        }
+    };
+
+    connect(d->ui.editCurrentPassword, &KPasswordLineEdit::passwordChanged, this, updateIsValid);
+    connect(d->ui.editNewPassword, &KNewPasswordWidget::passwordStatusChanged, this, updateIsValid);
+}
+
+PasswordChangeWidget::~PasswordChangeWidget()
